package ai.fitnova.security;
import ai.fitnova.repo.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import lombok.RequiredArgsConstructor; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component @RequiredArgsConstructor public class JwtFilter extends OncePerRequestFilter {private final JwtService jwt; private final UserRepository users; protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Long id=jwt.userId(h.substring(7));users.findById(id).ifPresent(u->SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of())));}catch(Exception ignored){}chain.doFilter(req,res);}}
